SELECT kind,name,definition FROM (
 SELECT 'schema' AS kind,'database' AS name,CAST(JSON_ARRAY(DEFAULT_CHARACTER_SET_NAME,DEFAULT_COLLATION_NAME) AS CHAR) AS definition FROM information_schema.SCHEMATA WHERE SCHEMA_NAME=DATABASE()
 UNION ALL SELECT 'table',TABLE_NAME,CAST(JSON_ARRAY(TABLE_TYPE,ENGINE,ROW_FORMAT,TABLE_COLLATION,CREATE_OPTIONS,TABLE_COMMENT) AS CHAR) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME NOT IN ('pushgo_product_owner','pushgo_ordinary_cutover')
 UNION ALL SELECT 'column',CONCAT(TABLE_NAME,'.',LPAD(ORDINAL_POSITION,6,'0')),CAST(JSON_ARRAY(COLUMN_NAME,COLUMN_TYPE,IS_NULLABLE,COLUMN_DEFAULT,EXTRA,GENERATION_EXPRESSION,CHARACTER_SET_NAME,COLLATION_NAME,COLUMN_COMMENT) AS CHAR) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME NOT IN ('pushgo_product_owner','pushgo_ordinary_cutover')
 UNION ALL SELECT 'index',CONCAT(TABLE_NAME,'.',INDEX_NAME,'.',LPAD(SEQ_IN_INDEX,6,'0')),CAST(JSON_ARRAY(NON_UNIQUE,COLUMN_NAME,SUB_PART,COLLATION,INDEX_TYPE,IS_VISIBLE,EXPRESSION,INDEX_COMMENT) AS CHAR) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME NOT IN ('pushgo_product_owner','pushgo_ordinary_cutover')
 UNION ALL SELECT 'constraint',CONCAT(TABLE_NAME,'.',CONSTRAINT_NAME),CAST(JSON_ARRAY(CONSTRAINT_TYPE,ENFORCED) AS CHAR) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME NOT IN ('pushgo_product_owner','pushgo_ordinary_cutover')
 UNION ALL SELECT 'key',CONCAT(TABLE_NAME,'.',CONSTRAINT_NAME,'.',LPAD(ORDINAL_POSITION,6,'0')),CAST(JSON_ARRAY(COLUMN_NAME,POSITION_IN_UNIQUE_CONSTRAINT,IF(REFERENCED_TABLE_SCHEMA=DATABASE(),'CURRENT',REFERENCED_TABLE_SCHEMA),REFERENCED_TABLE_NAME,REFERENCED_COLUMN_NAME) AS CHAR) FROM information_schema.KEY_COLUMN_USAGE WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME NOT IN ('pushgo_product_owner','pushgo_ordinary_cutover')
 UNION ALL SELECT 'check',c.CONSTRAINT_NAME,CAST(JSON_ARRAY(c.CHECK_CLAUSE) AS CHAR) FROM information_schema.CHECK_CONSTRAINTS c JOIN information_schema.TABLE_CONSTRAINTS t ON t.CONSTRAINT_SCHEMA=c.CONSTRAINT_SCHEMA AND t.CONSTRAINT_NAME=c.CONSTRAINT_NAME WHERE c.CONSTRAINT_SCHEMA=DATABASE() AND t.TABLE_NAME NOT IN ('pushgo_product_owner','pushgo_ordinary_cutover')
 UNION ALL SELECT 'foreign',CONCAT(TABLE_NAME,'.',CONSTRAINT_NAME),CAST(JSON_ARRAY(UNIQUE_CONSTRAINT_NAME,MATCH_OPTION,UPDATE_RULE,DELETE_RULE,REFERENCED_TABLE_NAME) AS CHAR) FROM information_schema.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE()
 UNION ALL SELECT 'partition',CONCAT(TABLE_NAME,'.',COALESCE(PARTITION_NAME,''),'.',COALESCE(SUBPARTITION_NAME,'')),CAST(JSON_ARRAY(PARTITION_METHOD,SUBPARTITION_METHOD,PARTITION_EXPRESSION,SUBPARTITION_EXPRESSION,PARTITION_DESCRIPTION,TABLESPACE_NAME) AS CHAR) FROM information_schema.PARTITIONS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME NOT IN ('pushgo_product_owner','pushgo_ordinary_cutover')
 UNION ALL SELECT 'view',TABLE_NAME,CAST(JSON_ARRAY(VIEW_DEFINITION,CHECK_OPTION,IS_UPDATABLE,DEFINER,SECURITY_TYPE,CHARACTER_SET_CLIENT,COLLATION_CONNECTION) AS CHAR) FROM information_schema.VIEWS WHERE TABLE_SCHEMA=DATABASE()
 UNION ALL SELECT 'trigger',TRIGGER_NAME,CAST(JSON_ARRAY(EVENT_MANIPULATION,EVENT_OBJECT_TABLE,ACTION_ORDER,ACTION_CONDITION,ACTION_STATEMENT,ACTION_ORIENTATION,ACTION_TIMING,SQL_MODE,DEFINER,CHARACTER_SET_CLIENT,COLLATION_CONNECTION,DATABASE_COLLATION) AS CHAR) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE()
 UNION ALL SELECT 'routine',SPECIFIC_NAME,CAST(JSON_ARRAY(ROUTINE_TYPE,DATA_TYPE,ROUTINE_DEFINITION,IS_DETERMINISTIC,SQL_DATA_ACCESS,SECURITY_TYPE,SQL_MODE,DEFINER,CHARACTER_SET_CLIENT,COLLATION_CONNECTION,DATABASE_COLLATION) AS CHAR) FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA=DATABASE()
 UNION ALL SELECT 'event',EVENT_NAME,CAST(JSON_ARRAY(DEFINER,TIME_ZONE,EVENT_DEFINITION,EVENT_TYPE,EXECUTE_AT,INTERVAL_VALUE,INTERVAL_FIELD,SQL_MODE,STARTS,ENDS,STATUS,ON_COMPLETION,CHARACTER_SET_CLIENT,COLLATION_CONNECTION,DATABASE_COLLATION) AS CHAR) FROM information_schema.EVENTS WHERE EVENT_SCHEMA=DATABASE()
) AS objects ORDER BY BINARY kind,BINARY name
